// SetFlowFilter sets a FlowFilter field's filter expression (SETFILTER on a
// FlowFilter field); FlowFields applying it use it from then on. "" clears it.
func (t *AccScheduleLine) SetFlowFilter(field, expr string) error {
	switch field {
	case "date_filter":
		if err := flowfilter.Validate(flowfilter.KindDate, expr); err != nil {
			return err
		}
		t.Date_filter = expr
		return nil
	case "dimension_1_filter":
		if err := flowfilter.Validate(flowfilter.KindCode, expr); err != nil {
			return err
		}
		t.Dimension_1_filter = expr
		return nil
	case "dimension_2_filter":
		if err := flowfilter.Validate(flowfilter.KindCode, expr); err != nil {
			return err
		}
		t.Dimension_2_filter = expr
		return nil
	case "budget_filter":
		if err := flowfilter.Validate(flowfilter.KindCode, expr); err != nil {
			return err
		}
		t.Budget_filter = expr
		return nil
	case "use_add_rpt_curr":
		if err := flowfilter.Validate(flowfilter.KindBool, expr); err != nil {
			return err
		}
		t.Use_add_rpt_curr = expr
		return nil
	}
	return fmt.Errorf("%q is not a FlowFilter field of Acc_Schedule_Line", field)
}

